mapper.select:
select t.id as templateId, t.template_name, t.alarm_type_value, t.template_status, t.creator, t.create_time, t.modifier, t.update_time, count(distinct (r.id)) as unionRegionCount, s.type_name as alarmTypeName, t.valid_start_date, t.valid_end_date, t.valid_start_time, t.valid_end_time, t.template_json, t.sync_status, t.task_id from vm_radar_alarm_template t left join sys_alarm_type s on t.alarm_type_value = s.type_value left join vm_radar_alarm_template_region_rel r on r.template_id = t.id and r.tenant_id = t.tenant_id and r.industry_code = t.industry_code where t.delete_flag = '0' and s.delete_flag = '0'
and t.template_name like CONCAT('%', #{dto.templateName}, '%')
and t.template_status = #{dto.templateStatus}
and t.alarm_type_value in
#{item}
and t.task_id in
#{item}
and t.creator like CONCAT('%', #{dto.creator}, '%')
${dto.dataScope}
and t.modifier like CONCAT('%', #{dto.modifier}, '%')
and t.create_time >= #{dto.createTimeBegin}
and t.create_time <= #{dto.createTimeEnd}
and t.update_time >= #{dto.updateTimeBegin}
and t.update_time <= #{dto.updateTimeEnd}
group by t.id
having unionRegionCount > 0
having unionRegionCount = 0
order by t.create_time
asc
desc
order by t.update_time
asc
desc
order by t.create_time desc

select
t.template_name
from vm_radar_alarm_template t
where t.tenant_id = #{tenantId}
and t.industry_code = #{industryCode}
and t.delete_flag = '0'

    and t.id != #{templateId}

mapper.update:
update
vm_radar_alarm_template t
set t.delete_flag = '1'
where t.id = #{param.templateId}
and t.tenant_id = #{param.tenantId}
and t.industry_code = #{param.industryCode}
and t.template_status = '0'

mapper.delete:
delete
from vm_radar_alarm_template_region_rel t
where
t.template_id = #{param.templateId}
and t.tenant_id = #{param.tenantId}
and t.industry_code = #{param.industryCode}

    and t.region_id = #{param.regionId}
